AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx, Flow *f, uint8_t *buf, uint32_t buflen,
    uint8_t ipproto, uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    /* Check if passive monitoring is complete */
    if (!FlowGetAppProto(f)) {
        /* Try passive protocol detection */
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            /* If DCERPC over UDP, continue checking with other methods */
            if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                AppProto pp_alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
                if (pp_alproto != ALPROTO_UNKNOWN) {
                    alproto = pp_alproto;
                }
            }
        } else {
            alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        }
    }

    /* If still unknown, check expectation list */
    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppLayerProto(f)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
            alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        }
    } else {
        alproto = FlowGetAppLayerProto(f);
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

    return alproto;
}

AppProto AppLayerProtoDetect(const AppLayerProtoDetectThreadCtx *tctx, Flow *f,
                             uint8_t *buf, uint32_t buflen, uint8_t ipproto,
                             uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowHasCompletedPassiveMonitoring(f)) {
        alproto = AppLayerProtoDetectByPassive(f, ipproto, direction);
        if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
            alproto = AppLayerProtoDetectByContent(f, buf, buflen, ipproto, direction);
        }
    } else {
        alproto = AppLayerProtoDetectByPostProcess(f, ipproto, direction);
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectByExpectation(f, ipproto, direction);
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowPMCompleted(f, direction)) {
        AppProto pm_alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (pm_alproto != ALPROTO_UNKNOWN) {
            alproto = pm_alproto;
            if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                AppProto dcerpc_udp_alproto = AppLayerProtoDetectDCERPCUDP(tctx, f, buf, buflen, direction);
                if (dcerpc_udp_alproto != ALPROTO_UNKNOWN) {
                    alproto = dcerpc_udp_alproto;
                }
            }
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        AppProto pp_alproto = AppLayerProtoDetectPP(tctx, f, ipproto, direction);
        if (pp_alproto != ALPROTO_UNKNOWN) {
            alproto = pp_alproto;
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        AppProto exp_alproto = AppLayerProtoDetectExpectation(f, ipproto);
        if (exp_alproto != ALPROTO_UNKNOWN) {
            alproto = exp_alproto;
        }
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx, Flow *f,
                                   uint8_t *buf, uint32_t buflen, uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProtoDetectionComplete(f, direction)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                AppProto d = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
                if (d != ALPROTO_UNKNOWN)
                    alproto = d;
            }

            FlowSetAppProtoDetectionComplete(f, direction);
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

    return alproto;
}
